%[text] Load Data
fname= 'titration_data.xlsx';
M=readmatrix(fname,'Sheet','Ce4+ titration','Range','D3:E29');
vol=M(:,1);
E=M(:,2) ./ 1000;
%[text] First Derivative Data Processing
Vavg1 = (vol(1:end-1) + vol(2:end))./2;
dE = E(2:end)-E(1:end-1);
dV1 = vol(2:end)-vol(1:end-1);
dEdV = dE ./ dV1;
%[text] Second Derivative Data Processing
Vavg2 = (Vavg1(1:end-1) + Vavg1(2:end)) ./ 2;
ddEdV = dEdV(2:end)-dEdV(1:end-1);
dV2 = Vavg1(2:end)-Vavg1(1:end-1);
SecondDerivative = ddEdV ./ dV2;
%[text] Plotting E to vol
plot (vol,E,'-o','color',[0,0,0],'MarkerFaceColor',[1,1,1],'MarkerSize',4); %[output:6b563177]
grid on;xlabel('Volume of Ce(NH_4)_4(SO_4)_4 added (mL)'); ylabel('E (V)'); %[output:6b563177]
title('Potential Against Volume of Ce(NH_4)_4(SO_4)_4 added'); %[output:6b563177]
%[text] First Derivative Plot
plot (Vavg1,dEdV,'-o','color',[0,0,0],'MarkerFaceColor',[1,1,1],'MarkerSize',4); %[output:1fd75fbe]
grid on;xlabel('Volume of Ce(NH_4)_4(SO_4)_4 added (mL)'); %[output:1fd75fbe]
ylabel('{\Delta}E/{\Delta}V'); %[output:1fd75fbe]
title('First Derivative Graph'); %[output:1fd75fbe]
%[text] Second Derivative Plot
plot (Vavg2,SecondDerivative,'-o','color',[0,0,0],'MarkerFaceColor',[1,1,1],'MarkerSize',4); %[output:51577bf9]
grid on;xlabel('Volume of Ce(NH_4)_4(SO_4)_4 added (mL)'); %[output:51577bf9]
ylabel('{\Delta}^{2}E/{\Delta}V^{2}'); %[output:51577bf9]
title('Second Derivative Graph'); %[output:51577bf9]
%[text] Equivalence Point of Each Graph
EqA = (vol(15) + vol(16)) / 2 %[output:9c1d47d3]
EqB = 5.05 %[output:2208fd62]
EqC = interp1(SecondDerivative(14:15), Vavg2(14:15), 0) %[output:6a283ff5]

Vex = interp1(vol,E,EqC/2) %[output:267aadc6]

